// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BundleReleaseTracks) predicate.BundleReleaseTracks {
	return predicate.BundleReleaseTracks(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BundleReleaseTracks) predicate.BundleReleaseTracks {
	return predicate.BundleReleaseTracks(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BundleReleaseTracks) predicate.BundleReleaseTracks {
	return predicate.BundleReleaseTracks(sql.NotPredicates(p))
}
